  EXEC sp_executesql N'SET @ok = IIF(EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N''dbo.Orders'') AND name = N''pk_orders'' AND is_primary_key = 1 AND type_desc = N''NONCLUSTERED''), 1, 0);
