ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. cix_orders_date is the CLUSTERED index on (orderDate, orderID) | cix_orders_date là chỉ mục CLUSTERED trên (orderDate, orderID)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

