WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. The table is no longer a heap and duplicates of orderID are rejected | Bảng không còn là heap và orderID trùng bị từ chối'; END
