  AND EXISTS (SELECT 1 FROM (SELECT c.name AS col, ic.key_ordinal FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id
JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id WHERE i.object_id = OBJECT_ID(N''dbo.Orders'') AND i.name = N''cix_orders_date'' AND ic.is_included_column = 0) x WHERE x.col = N''orderDate'' AND x.key_ordinal = 1)
  AND EXISTS (SELECT 1 FROM (SELECT c.name AS col, ic.key_ordinal FROM sys.indexes i JOIN sys.index_columns ic ON ic.object_id = i.object_id AND ic.index_id = i.index_id
JOIN sys.columns c ON c.object_id = ic.object_id AND c.column_id = ic.column_id WHERE i.object_id = OBJECT_ID(N''dbo.Orders'') AND i.name = N''cix_orders_date'' AND ic.is_included_column = 0) x WHERE x.col = N''orderID'' AND x.key_ordinal = 2), 1, 0);
SET @info = N''expected CREATE CLUSTERED INDEX cix_orders_date ON Orders (orderDate, orderID)'';',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 2. cix_orders_date is the CLUSTERED index on (orderDate, orderID) | cix_orders_date là chỉ mục CLUSTERED trên (orderDate, orderID)'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 2. cix_orders_date is the CLUSTERED index on (orderDate, orderID) | cix_orders_date là chỉ mục CLUSTERED trên (orderDate, orderID)', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

-- CHECK 3: The table is no longer a heap and duplicates of orderID are rejected
SELECT @ok = 0, @info = NULL;
BEGIN TRY
  EXEC sp_executesql N'DECLARE @n INT = 0; BEGIN TRAN; BEGIN TRY INSERT INTO Orders VALUES (1, 12, ''2026-10-05'', 1); END TRY BEGIN CATCH SET @n = 1; END CATCH; IF @@TRANCOUNT > 0 ROLLBACK;
SET @ok = IIF(@n = 1 AND NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id = OBJECT_ID(N''dbo.Orders'') AND type_desc = N''HEAP''), 1, 0); SET @info = N''a primary key on orderID must reject a second order 1'';',
    N'@ok BIT OUTPUT, @info NVARCHAR(4000) OUTPUT', @ok = @ok OUTPUT, @info = @info OUTPUT;
END TRY
BEGIN CATCH
  SELECT @ok = 0, @info = CONCAT(N'error ', ERROR_NUMBER(), N': ', ERROR_MESSAGE());
END CATCH;
WHILE @@TRANCOUNT > 0 ROLLBACK;
IF @ok = 1 BEGIN SET @pass += 1; PRINT N'PASS 3. The table is no longer a heap and duplicates of orderID are rejected | Bảng không còn là heap và orderID trùng bị từ chối'; END
ELSE BEGIN SET @fail += 1; PRINT CONCAT(N'FAIL 3. The table is no longer a heap and duplicates of orderID are rejected | Bảng không còn là heap và orderID trùng bị từ chối', CASE WHEN @info IS NULL THEN N'' ELSE CONCAT(N'  ⇒  ', @info) END); END

PRINT N'──────────────────────────────────────';
IF @fail = 0 PRINT CONCAT(N'ALL ', @pass, N' CHECKS PASSED — go back to Code Lab and press "Mark as solved".');
ELSE PRINT CONCAT(@pass, N' passed, ', @fail, N' FAILED — fix solution.sql, then run setup.sql, solution.sql, check.sql again.');
SELECT CASE WHEN @fail = 0 THEN N'ALL CHECKS PASSED' ELSE N'NOT YET' END AS Result, @pass AS Passed, @fail AS Failed;
IF @fail > 0 RAISERROR(N'%d check(s) failed', 16, 1, @fail);
